# Datenzugriff
class NotenRepo:
    def __init__(self):
        self.daten = {"Anna": [1, 2, 2]}
    def noten(self, name):
        return self.daten.get(name, [])

# Geschäftslogik
class NotenService:
    def __init__(self, repo):
        self.repo = repo
    def schnitt(self, name):
        n = self.repo.noten(name)
        return sum(n) / len(n) if n else None

# Präsentation
svc = NotenService(NotenRepo())
print(f"Schnitt: {svc.schnitt('Anna'):.2f}")
# Schnitt: 1.67

class Model:
    def __init__(self):
        self.todos = []

class View:
    def zeige(self, todos):
        for i, t in enumerate(todos, 1):
            print(f"{i}. {t}")

class Controller:
    def __init__(self, m, v):
        self.m, self.v = m, v
    def neu(self, text):
        if text.strip():
            self.m.todos.append(text)
        self.v.zeige(self.m.todos)

c = Controller(Model(), View())
c.neu("Matura-Projekt")
c.neu("   ")  # leer: ignoriert
# 1. Matura-Projekt
