class ViewModel:
    def __init__(self):
        self._name = ""
        self.beobachter = []

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, wert):
        self._name = wert
        for f in self.beobachter:
            f("name")  # melden

    @property
    def gruss(self):
        return f"Servus, {self._name}!"

vm = ViewModel()
vm.beobachter.append(
    lambda p: print("View neu:", vm.gruss))
vm.name = "Lea"
# View neu: Servus, Lea!

class MainVm : INotifyPropertyChanged
{
  public event
    PropertyChangedEventHandler?
    PropertyChanged;
  string name = "";
  public string Name {
    get => name;
    set {
      name = value;
      PropertyChanged?.Invoke(this,
        new(nameof(Name)));
    }
  }
}

